    id: 2,
    firstName: 'Ransom',
    lastName: 'Aslie',
    memberCardNumber: '8047727435',
    policyNumber: '6494400124',
    dataOfBirth: '04/09/2012',
  },
];

@Injectable({
  providedIn: 'root',
})
export class MemberService {
